function emptyTeste(turnoDefault, pcfg) {
  return {
    id: (typeof crypto!=="undefined"&&crypto.randomUUID) ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2,10)}-${Math.random().toString(36).slice(2,10)}`,
    data: todayStr(),
    hora: nowTime(),
    turno: turnoDefault||"Diurno",
    quemFez: "",
    quemFezId: "",
    centralAcompanhou: "",
    centralId: "",
    zonas: Object.fromEntries(pcfg.zonas.map(z=>[z,{status:"ok",obs:""}])),
    criadoEm: new Date().toISOString(),
  };
}

function PinGate({ onSuccess, onBack, dark, project, pcfg }) {
  const S = getStyles(dark);
  const [pin, setPin] = useState("");
  const [err, setErr] = useState(false);
  const pinLider = PROJECT_PINS[project.id];
  const tryPin = () => {
    if(pin==="601604"){ grantSession("demo"); onSuccess("admin"); return; } // PIN GAL demo
    if(pin===PIN_ADMIN){ onSuccess("admin"); return; }
    if(pinLider && pin===pinLider){ onSuccess("lider"); return; }
    setErr(true);
  };
  return (
    <div style={{...S.page,alignItems:"center",justifyContent:"center"}}>
      <div style={{...S.card,maxWidth:320,width:"100%",margin:16,textAlign:"center"}}>
        <div style={{fontSize:32,marginBottom:8}}>🔒</div>
        <div style={{fontSize:16,fontWeight:800,...S.txt,marginBottom:4}}>Teste Perimetral</div>
        <div style={{fontSize:12,...S.txt2,marginBottom:20}}>{project.id} · {pcfg.clienteNome||project.name}</div>
        <input type="password" inputMode="numeric" placeholder="PIN" maxLength={8}
          value={pin} onChange={e=>{setPin(e.target.value);setErr(false);}}
          onKeyDown={e=>{if(e.key==="Enter") tryPin();}}
          style={{...S.inp,textAlign:"center",fontSize:22,letterSpacing:10,marginBottom:8}}/>
        {err&&<div style={{fontSize:12,color:"#ef4444",marginBottom:8}}>PIN incorreto</div>}
        <div style={{display:"flex",gap:8}}>
          <button onClick={onBack} style={{...S.btnSec,flex:1,fontSize:13}}>← Voltar</button>
          <button onClick={tryPin} style={{...S.btn,flex:1,fontSize:13}}>Entrar</button>
        </div>
      </div>
    </div>
  );
}

export default function Perimetral({ project, onBack, dark, onToggleTheme, sharedAuth, onAuthGranted }) {
  const S = getStyles(dark||true);
  const pcfg = getPerimetralConfig(project.id);
  const [authLevel, setAuthLevel] = useState(()=>sharedAuth||getAccess(project?.id)||null);
  const [screen, setScreen] = useState(()=>(sharedAuth||getAccess(project?.id))?"list":"pin");
  const [testes, setTestes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState(null);
  const [viewTeste, setViewTeste] = useState(null);
  const [equipe, setEquipe] = useState([]);
  const [filtroTurno, setFiltroTurno] = useState("Todos");
  const [filtroPeriodo, setFiltroPeriodo] = useState("7");
  const [showConsolidado, setShowConsolidado] = useState(false);
  const [modoSelecao, setModoSelecao] = useState(false);
  const [pdfSel, setPdfSel] = useState(null); // {modo:"teste"|"consolidado", teste?, testes?, periodo?, perim:bool, rondas:bool}
  const [selecionados, setSelecionados] = useState([]);

  const adminAuth = authLevel==="admin";

  const rondaTimer = useRef(null);
  const rondaPend = useRef(null); // teste com ronda pendente de gravação (debounce)

  useEffect(()=>{
    loadTestes(project.id).then(t=>{ setTestes(t||[]); setLoading(false); });
    loadEquipe(project.id).then(e=>setEquipe(e||[]));
    return ()=>{
      if(rondaTimer.current) clearTimeout(rondaTimer.current);
      if(rondaPend.current) saveTesteMerge(project.id, rondaPend.current); // não perde a última digitação
    };
  },[project.id]); // eslint-disable-line

  // ── Continuidade da Ronda (registros livres ao longo do plantão, dentro do teste)
  // Regra de equipe: todos os ativos, exceto Porteiro, CDA e CCO/Central.
  const normP = (s)=>String(s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
  const colabsRonda = equipe
    .filter(c=>(c.status||"ativo")==="ativo" && (c.nome||"").trim())
    .filter(c=>{ const cg=normP(c.cargo); if(cg.includes("folg")) return true; return !["porteiro","cda","cco","central"].some(x=>cg.includes(x)); })
    .sort((a,b)=>normP(a.nome).localeCompare(normP(b.nome)));

  const persistViewTeste = (novo, imediato=false) => {
    setViewTeste(novo);
    setTestes(ts=>ts.some(t=>t.id===novo.id)?ts.map(t=>t.id===novo.id?novo:t):ts); // atualização otimista
    rondaPend.current = novo;
    if(rondaTimer.current) clearTimeout(rondaTimer.current);
    const doSave = async ()=>{
      rondaPend.current = null;
      setSaving(true);
      const novos = await saveTesteMerge(project.id, novo);
      setTestes(novos);
      setSaving(false);
    };
    if(imediato) doSave();
    else rondaTimer.current = setTimeout(doSave, 1200);
  };
  const addRondaCont = () => {
    if(!viewTeste) return;
    const r = { id:newRid(), hora:nowTime(), executante:viewTeste.quemFez||"", obs:"", criadoEm:new Date().toISOString() };
    persistViewTeste({ ...viewTeste, rondas:[...(viewTeste.rondas||[]), r] }, true);
  };
  const editRondaCont = (rid,campo,valor,imediato=true) =>
    persistViewTeste({ ...viewTeste, rondas:(viewTeste.rondas||[]).map(r=>r.id===rid?{...r,[campo]:valor}:r) }, imediato);
  const delRondaCont = (rid) =>
    persistViewTeste({ ...viewTeste, rondas:(viewTeste.rondas||[]).filter(r=>r.id!==rid) }, true);

  // Get filtered colaboradores by turno
  const getColabsByTurno = (turno) => equipe.filter(c=>
    c.status==="ativo" && (c.turno===turno || c.cargo?.toLowerCase().includes("líder") || c.cargo?.toLowerCase().includes("lider"))
  );
  const getCCOs = () => equipe.filter(c=>
    c.status==="ativo" && (c.cargo?.toLowerCase().includes("cco") || c.cargo?.toLowerCase().includes("central"))
  );

  const updateZona = (zona, field, val) => {
    setForm(f=>({...f, zonas:{...f.zonas,[zona]:{...f.zonas[zona],[field]:val}}}));
  };

  const salvar = async () => {
    if(!form.quemFez.trim()) { alert("Informe quem realizou o teste"); return; }
    setSaving(true);
    try {
      const novo = {...form, criadoEm:new Date().toISOString()};
      const newList = await saveTesteMerge(project.id, novo);
      setTestes(newList);
      setScreen("list");
      setForm(null);
    } catch(e){ alert("Erro ao salvar"); }
    setSaving(false);
  };

  const excluir = async (id) => {
    if(!window.confirm("Excluir este teste?")) return;
    const newList = await deleteTesteMerge(project.id, id);
    setTestes(newList);
    setViewTeste(null); setScreen("list");
  };

  // Filtered testes for archive view
  const testesFiltrados = testes.filter(t=>{
    const matchTurno = filtroTurno==="Todos"||t.turno===filtroTurno;
    const hoje = new Date();
    const dataT = new Date(t.data+"T12:00:00");
    const diff = Math.floor((hoje-dataT)/86400000);
    const matchPeriodo = filtroPeriodo==="all"||(diff<=parseInt(filtroPeriodo));
    return matchTurno && matchPeriodo;
  });

  // Group by date for archive display
  const grouped = {};
  testesFiltrados.forEach(t=>{
    if(!grouped[t.data]) grouped[t.data]=[];
    grouped[t.data].push(t);
  });
  const sortedDates = Object.keys(grouped).sort((a,b)=>b.localeCompare(a));

  if(screen==="pin") return <PinGate project={project} pcfg={pcfg} dark={dark||true} onBack={onBack} onSuccess={(l)=>{grantSession(l,project.id);setAuthLevel(l);setScreen("list");onAuthGranted?.(l);}}/>;

  // ── Projeto ainda sem zonas/mapa cadastrados — aguardando configuração
  if(pcfg.zonas.length===0) return (
    <div style={{...S.page,alignItems:"center",justifyContent:"center"}}>
      <div style={{...S.card,maxWidth:340,width:"100%",margin:16,textAlign:"center"}}>
        <div style={{fontSize:32,marginBottom:8}}>🚧</div>
        <div style={{fontSize:16,fontWeight:800,...S.txt,marginBottom:6}}>Teste Perimetral</div>
        <div style={{fontSize:12,...S.txt2,marginBottom:16}}>{project.id} · {project.name}</div>
        <div style={{fontSize:13,...S.txt2,lineHeight:1.5,marginBottom:18}}>
          Este projeto ainda não tem as zonas e o mapa perimetral cadastrados.
          Em breve o Moked configura isso aqui — assim que as zonas forem definidas, o teste fica disponível automaticamente.
        </div>
        <button onClick={onBack} style={{...S.btn,width:"100%",fontSize:13}}>← Voltar</button>
      </div>
    </div>
  );

  if(loading) return (
    <div style={{...S.page,alignItems:"center",justifyContent:"center"}}>
      <div style={{textAlign:"center"}}><div style={{fontSize:30,marginBottom:10}}>🔒</div><div style={{fontSize:13,...S.txt2}}>Carregando...</div></div>
    </div>
  );

  // ── Modal seletor de conteúdo do PDF (somente PIN gerencial)
  const nRondasSel = pdfSel
    ? (pdfSel.modo==="teste"
        ? (pdfSel.teste?.rondas||[]).length
        : (pdfSel.testes||[]).reduce((acc,t)=>acc+((t.rondas||[]).length),0))
    : 0;
  const podeGerar = !!pdfSel && (pdfSel.perim || (pdfSel.rondas && nRondasSel>0));
  const PdfSelector = pdfSel ? (
    <div onClick={()=>setPdfSel(null)}
      style={{position:"fixed",inset:0,background:"#000000cc",zIndex:100,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div onClick={e=>e.stopPropagation()}
        style={{...S.card,width:"100%",maxWidth:380,padding:18,display:"flex",flexDirection:"column",gap:12}}>
        <div>
          <div style={{fontSize:15,fontWeight:800,...S.txt}}>📄 Conteúdo do relatório</div>
          <div style={{fontSize:11,...S.txt2,marginTop:3}}>
            {pdfSel.modo==="teste"
              ? `${pdfSel.teste.turno} · ${fmtDate(pdfSel.teste.data)}`
              : pdfSel.periodo}
          </div>
        </div>

        {[
          {k:"perim",  ic:"🔒", t:"Teste Perimetral", d:"Mapa com as zonas, status de cada zona e histórico de falhas", n:null, off:false},
          {k:"rondas", ic:"🚶", t:"Rondas Adicionais", d:"Continuidade da ronda — registros de área ao longo do plantão", n:nRondasSel, off:nRondasSel===0},
        ].map(o=>(
          <button key={o.k} disabled={o.off}
            onClick={()=>setPdfSel({...pdfSel,[o.k]:!pdfSel[o.k]})}
            style={{textAlign:"left",padding:"12px 13px",borderRadius:10,cursor:o.off?"not-allowed":"pointer",
              opacity:o.off?0.45:1,
              background:pdfSel[o.k]?"#a855f715":(dark?"#0b1220":"#f8fafc"),
              border:`1px solid ${pdfSel[o.k]?"#a855f7":(dark?"#1e293b":"#e2e8f0")}`}}>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <span style={{fontSize:14}}>{pdfSel[o.k]?"\u2611":"\u2610"}</span>
              <span style={{fontSize:13,fontWeight:700,...S.txt}}>{o.ic} {o.t}</span>
              {o.n!==null && <span style={{marginLeft:"auto",fontSize:10,...S.txt2}}>{o.n} registro(s)</span>}
            </div>
            <div style={{fontSize:10,...S.txt2,marginTop:4,paddingLeft:22}}>
              {o.off ? "Nenhuma ronda adicional registrada" : o.d}
            </div>
          </button>
        ))}

        <div style={{display:"flex",gap:8,marginTop:2}}>
          <button onClick={()=>setPdfSel(null)} style={{...S.btnSec,flex:1,fontSize:13}}>Cancelar</button>
          <button disabled={!podeGerar}
            onClick={()=>{
              const sel=pdfSel; setPdfSel(null);
              if(sel.modo==="teste") gerarPDFTeste(sel.teste,testes,project,pcfg,sel.rondas,sel.perim);
              else gerarPDFConsolidado(sel.testes,sel.periodo,project,pcfg,sel.rondas,sel.perim);
            }}
            style={{...S.btnSm,flex:1,fontSize:13,padding:"11px 0",justifyContent:"center",
              opacity:podeGerar?1:0.4,cursor:podeGerar?"pointer":"not-allowed",
              color:"#a855f7",border:"1px solid #a855f744",background:"#a855f712"}}>
            📄 Gerar PDF
          </button>
        </div>
        {!podeGerar && <div style={{fontSize:10,color:"#f59e0b",textAlign:"center"}}>Marque ao menos uma seção.</div>}
      </div>
    </div>
  ) : null;

  // ── VIEW teste individual
  if(screen==="view"&&viewTeste) {
    const probs = pcfg.zonas.filter(z=>(viewTeste.zonas[z]?.status||"ok")!=="ok").length;
    return (
      <div style={S.page}>
        {PdfSelector}
        <div style={S.wrap}>
          <div style={{position:"sticky",top:0,zIndex:10,...S.hdrBg,padding:"14px 16px"}}>
            <div style={{display:"flex",alignItems:"center",gap:10}}>
              <button onClick={()=>{setViewTeste(null);setScreen("list");}} style={S.backBtn}>← Voltar</button>
              <div style={{flex:1}}>
                <div style={{fontSize:15,fontWeight:800,...S.txt}}>{viewTeste.turno==="Diurno"?"☀️":"🌙"} {viewTeste.turno} · {fmtDate(viewTeste.data)}</div>
                <div style={{fontSize:11,...S.txt2}}>{viewTeste.quemFez||"—"} · {viewTeste.hora}</div>
              </div>
              {adminAuth && (
                <button onClick={()=>setPdfSel({modo:"teste",teste:viewTeste,perim:true,rondas:(viewTeste.rondas||[]).length>0})}
                  style={{...S.btnSm,color:"#a855f7",border:"1px solid #a855f744",fontSize:11}}>📄 PDF</button>
              )}
            </div>
          </div>
          <div style={{padding:"12px 16px",display:"flex",flexDirection:"column",gap:10}}>
            {/* KPIs */}
            <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>
              {[{l:"OK",v:pcfg.zonas.length-probs,c:"#22c55e"},{l:"Problemas",v:probs,c:"#ef4444"},{l:"Total",v:pcfg.zonas.length,c:"#0ea5e9"}].map(({l,v,c})=>(
                <div key={l} style={{...S.card,textAlign:"center",padding:"10px 8px"}}>
                  <div style={{fontSize:22,fontWeight:900,color:c}}>{v}</div>
                  <div style={{fontSize:9,...S.txt2,fontWeight:700}}>{l}</div>
                </div>
              ))}
            </div>
            {/* Mini mapa */}
            <div style={S.card}>
              <div style={{fontSize:10,...S.txt2,fontWeight:700,textTransform:"uppercase",marginBottom:8}}>🗺️ Mapa</div>
              <MapaPerimetral zonas={viewTeste.zonas} size="normal" pcfg={pcfg}/>
            </div>
            {/* Zonas */}
            <div style={S.card}>
              <div style={{fontSize:10,...S.txt2,fontWeight:700,textTransform:"uppercase",marginBottom:10}}>🔒 Status das Zonas</div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6}}>
                {pcfg.zonas.map(zona=>{
                  const zd = viewTeste.zonas[zona]||{status:"ok",obs:""};
                  const cfg = STATUS_CFG[zd.status]||STATUS_CFG.ok;
                  return (
                    <div key={zona} style={{display:"flex",alignItems:"center",gap:6,padding:"6px 8px",borderRadius:7,background:zd.status!=="ok"?cfg.bg:"transparent",border:`1px solid ${zd.status!=="ok"?cfg.border:"transparent"}`}}>
                      <div style={{width:8,height:8,borderRadius:"50%",background:cfg.dot,flexShrink:0}}/>
                      <span style={{fontSize:11,fontWeight:700,...S.txt}}>{zona.replace("Zona ","Z-")}</span>
                      <span style={{fontSize:10,color:cfg.color,fontWeight:700,marginLeft:"auto"}}>{cfg.label}</span>
                    </div>
                  );
                })}
              </div>
              {/* Observações dos problemas */}
              {pcfg.zonas.filter(z=>(viewTeste.zonas[z]?.status||"ok")!=="ok"&&viewTeste.zonas[z]?.obs).map(z=>(
                <div key={z} style={{marginTop:6,padding:"6px 10px",background:dark?"#020510":"#f8fafc",borderRadius:7,fontSize:11,...S.txt2}}>
                  <span style={{fontWeight:700,...S.txt}}>{z}:</span> {viewTeste.zonas[z].obs}
                </div>
              ))}
            </div>
            {/* Continuidade da Ronda — registros livres ao longo do plantão */}
            <div style={S.card}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:(viewTeste.rondas||[]).length>0?10:0}}>
                <div style={{fontSize:10,...S.txt2,fontWeight:700,textTransform:"uppercase"}}>🚶 Continuidade da Ronda ({(viewTeste.rondas||[]).length})</div>
                {saving && <span style={{fontSize:9,...S.txt2}}>salvando…</span>}
              </div>
              {(viewTeste.rondas||[]).map((r,i)=>(
                <div key={r.id} style={{border:`1px solid ${(dark||true)?"#0f172a":"#e2e8f0"}`,borderRadius:8,padding:"10px 12px",marginBottom:8}}>
                  <div style={{display:"flex",alignItems:"center",gap:8}}>
                    <span style={{width:8,height:8,borderRadius:"50%",background:"#22c55e",flexShrink:0}}/>
                    <div style={{fontSize:12,fontWeight:800,...S.txt,minWidth:62}}>Ronda {i+1}</div>
                    <input type="time" value={r.hora||""} onChange={e=>editRondaCont(r.id,"hora",e.target.value)}
                      style={{...S.inp,flex:1,fontSize:14,padding:"9px 10px"}}/>
                    {adminAuth && <button onClick={()=>delRondaCont(r.id)} style={{...S.btnSm,padding:"7px 9px",fontSize:12,color:"#ef4444",borderColor:"#ef444433"}}>🗑</button>}
                  </div>
                  <div style={{marginTop:8}}>
                    <label style={{...S.lbl,fontSize:9}}>👤 Executante</label>
                    <select value={r.executante||""} onChange={e=>editRondaCont(r.id,"executante",e.target.value)}
                      style={{...S.inp,fontSize:13,padding:"9px 10px"}}>
                      <option value="">— selecionar —</option>
                      {r.executante && !colabsRonda.some(c=>c.nome===r.executante) && <option value={r.executante}>{r.executante}</option>}
                      {colabsRonda.map(c=><option key={c.nome} value={c.nome}>{c.nome}{c.cargo?` · ${c.cargo}`:""}</option>)}
                    </select>
                  </div>
                  <input value={r.obs||""} onChange={e=>editRondaCont(r.id,"obs",e.target.value,false)}
                    placeholder="Observação (opcional)..." style={{...S.inp,fontSize:13,marginTop:8}}/>
                </div>
              ))}
              <button onClick={addRondaCont} style={{...S.btnGreen,fontSize:13,marginTop:(viewTeste.rondas||[]).length>0?2:10}}>➕ Registrar ronda (agora)</button>
            </div>
            {adminAuth&&<button onClick={()=>excluir(viewTeste.id)} style={{...S.btnSec,color:"#ef4444",borderColor:"#ef444433",fontSize:13}}>🗑 Excluir</button>}
          </div>
        </div>
      </div>
    );
  }

  // ── FORMULÁRIO
  if(screen==="form"&&form) {
    const colabs = colabsRonda; // todos os vigilantes ativos (exceto porteiro/CDA/CCO), ordenados por nome
    const ccos = equipe
      .filter(c=>(c.status||"ativo")==="ativo" && (c.nome||"").trim())
      .filter(c=>{ const cg=normP(c.cargo); return ["porteiro","cco","central","cda"].some(x=>cg.includes(x)); })
      .sort((a,b)=>normP(a.nome).localeCompare(normP(b.nome)));
    return (
      <div style={S.page}>
        <div style={S.wrap}>
          <div style={{position:"sticky",top:0,zIndex:10,...S.hdrBg,padding:"14px 16px"}}>
            <div style={{display:"flex",alignItems:"center",gap:10}}>
              <button onClick={()=>{setScreen("list");setForm(null);}} style={S.backBtn}>← Cancelar</button>
              <div style={{flex:1}}>
                <div style={{fontSize:15,fontWeight:800,...S.txt}}>🔒 Novo Teste Perimetral</div>
                <div style={{fontSize:11,...S.txt2}}>P505 · Klog Guarulhos</div>
              </div>
              <button onClick={onToggleTheme} style={{background:"transparent",border:`1px solid ${dark?"#1e293b":"#cbd5e1"}`,borderRadius:8,padding:"5px 10px",cursor:"pointer",fontSize:14,...S.txt2}}>{dark?"☀️":"🌙"}</button>
            </div>
          </div>

          <div style={{padding:"14px 16px",display:"flex",flexDirection:"column",gap:12}}>
            {/* Data, Hora, Turno */}
            <div style={{...S.card,display:"flex",flexDirection:"column",gap:10}}>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
                <div>
                  <label style={S.lbl}>Data</label>
                  <input type="date" value={form.data} onChange={e=>setForm(f=>({...f,data:e.target.value}))} style={S.inp}/>
                </div>
                <div>
                  <label style={S.lbl}>Hora</label>
                  <div style={{display:"flex",gap:5}}>
                    <input type="time" value={form.hora} onChange={e=>setForm(f=>({...f,hora:e.target.value}))} style={{...S.inp,flex:1}}/>
                    <button onClick={()=>setForm(f=>({...f,hora:nowTime()}))} style={{...S.btnSm,padding:"8px 10px",fontSize:14,flexShrink:0}}>⏱</button>
                  </div>
                </div>
              </div>
              {/* Turno */}
              <div>
                <label style={S.lbl}>Turno</label>
                <div style={{display:"flex",gap:8}}>
                  {["Diurno","Noturno"].map(t=>(
                    <button key={t} onClick={()=>setForm(f=>({...f,turno:t,quemFez:"",quemFezId:""}))}
                      style={{flex:1,background:form.turno===t?t==="Diurno"?"#1a2e1a":"#0a0a2e":"transparent",border:`2px solid ${form.turno===t?t==="Diurno"?"#22c55e":"#818cf8":"#0f172a"}`,color:form.turno===t?t==="Diurno"?"#22c55e":"#818cf8":dark?"#475569":"#94a3b8",borderRadius:8,padding:"10px",fontSize:13,cursor:"pointer",fontWeight:form.turno===t?700:400}}>
                      {t==="Diurno"?"☀️ Diurno":"🌙 Noturno"}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {/* Equipe — seleção automática */}
            <div style={{...S.card,display:"flex",flexDirection:"column",gap:10}}>
              <div style={{fontSize:11,color:"#0ea5e9",fontWeight:700,textTransform:"uppercase",letterSpacing:.8}}>👤 Equipe</div>
              {/* Quem fez o teste */}
              <div>
                <label style={S.lbl}>Realizou o Teste *</label>
                {colabs.length>0?(
                  <div style={{display:"flex",flexDirection:"column",gap:5}}>
                    {colabs.map(c=>(
                      <button key={c.id} onClick={()=>setForm(f=>({...f,quemFez:c.nome,quemFezId:c.id}))}
                        style={{display:"flex",alignItems:"center",gap:8,padding:"8px 12px",borderRadius:8,background:form.quemFezId===c.id?dark?"#001a2e":"#e0f2fe":"transparent",border:`1px solid ${form.quemFezId===c.id?"#0ea5e944":dark?"#0f172a":"#e2e8f0"}`,cursor:"pointer",textAlign:"left"}}>
                        <div style={{width:30,height:30,borderRadius:8,overflow:"hidden",flexShrink:0,background:dark?"#0f172a":"#f1f5f9",display:"flex",alignItems:"center",justifyContent:"center",fontSize:14}}>
                          {c.foto?<img src={c.foto} style={{width:"100%",height:"100%",objectFit:"cover"}} alt=""/>:"👤"}
                        </div>
                        <div style={{flex:1}}>
                          <div style={{fontSize:12,fontWeight:700,...S.txt}}>{c.nome}</div>
                          <div style={{fontSize:10,...S.txt2}}>{c.cargo} · {c.turno}</div>
                        </div>
                        {form.quemFezId===c.id&&<span style={{color:"#0ea5e9",fontSize:14}}>✓</span>}
                      </button>
                    ))}
                    {/* Manual fallback */}
                    <input value={form.quemFezId?"":form.quemFez} onChange={e=>setForm(f=>({...f,quemFez:e.target.value,quemFezId:""}))}
                      placeholder="Ou digitar nome manualmente..."
                      style={{...S.inp,fontSize:12,marginTop:4}}/>
                  </div>
                ):(
                  <input value={form.quemFez} onChange={e=>setForm(f=>({...f,quemFez:e.target.value}))} placeholder="Nome do responsável..." style={S.inp}/>
                )}
              </div>
              {/* Central */}
              <div>
                <label style={S.lbl}>Acompanhou na Central</label>
                {ccos.length>0?(
                  <div style={{display:"flex",flexDirection:"column",gap:5}}>
                    {ccos.map(c=>(
                      <button key={c.id} onClick={()=>setForm(f=>({...f,centralAcompanhou:c.nome,centralId:c.id}))}
                        style={{display:"flex",alignItems:"center",gap:8,padding:"7px 12px",borderRadius:8,background:form.centralId===c.id?dark?"#021a0d":"#dcfce7":"transparent",border:`1px solid ${form.centralId===c.id?"#22c55e44":dark?"#0f172a":"#e2e8f0"}`,cursor:"pointer",textAlign:"left"}}>
                        <div style={{width:28,height:28,borderRadius:7,overflow:"hidden",flexShrink:0,background:dark?"#0f172a":"#f1f5f9",display:"flex",alignItems:"center",justifyContent:"center",fontSize:13}}>
                          {c.foto?<img src={c.foto} style={{width:"100%",height:"100%",objectFit:"cover"}} alt=""/>:"👤"}
                        </div>
                        <div style={{flex:1}}>
                          <div style={{fontSize:12,fontWeight:700,...S.txt}}>{c.nome}</div>
                          <div style={{fontSize:10,...S.txt2}}>{c.cargo}</div>
                        </div>
                        {form.centralId===c.id&&<span style={{color:"#22c55e",fontSize:14}}>✓</span>}
                      </button>
                    ))}
                    <input value={form.centralId?"":form.centralAcompanhou} onChange={e=>setForm(f=>({...f,centralAcompanhou:e.target.value,centralId:""}))}
                      placeholder="Ou digitar nome manualmente..."
                      style={{...S.inp,fontSize:12,marginTop:4}}/>
                  </div>
                ):(
                  <input value={form.centralAcompanhou} onChange={e=>setForm(f=>({...f,centralAcompanhou:e.target.value}))} placeholder="Nome da operadora..." style={S.inp}/>
                )}
              </div>
            </div>

            {/* Zonas */}
            <div style={S.card}>
              <div style={{fontSize:11,color:"#0ea5e9",fontWeight:700,textTransform:"uppercase",letterSpacing:.8,marginBottom:12}}>🔒 Status das {pcfg.zonas.length} Zonas</div>
              {pcfg.zonas.map(zona=>{
                const zd = form.zonas[zona]||{status:"ok",obs:""};
                const temProb = zd.status!=="ok";
                return (
                  <div key={zona} style={{marginBottom:8,padding:"9px 12px",background:temProb?STATUS_CFG[zd.status].bg+"66":dark?"#020510":"#f8fafc",borderRadius:8,border:`1px solid ${temProb?STATUS_CFG[zd.status].border:dark?"#0f172a":"#e2e8f0"}`}}>
                    <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:temProb?8:0}}>
                      <span style={{fontSize:12,fontWeight:700,...S.txt,width:62,flexShrink:0}}>{zona.replace("Zona ","Z-")}</span>
                      <div style={{display:"flex",gap:5,flex:1}}>
                        {["ok","parcial","inop"].map(s=>{
                          const cfg = STATUS_CFG[s];
                          const isSel = zd.status===s;
                          return (
                            <button key={s} onClick={()=>updateZona(zona,"status",s)}
                              style={{flex:1,background:isSel?cfg.bg:"transparent",border:`2px solid ${isSel?cfg.color:dark?"#0f172a":"#e2e8f0"}`,color:isSel?cfg.color:dark?"#334155":"#94a3b8",borderRadius:6,padding:"5px 4px",fontSize:10,cursor:"pointer",fontWeight:isSel?700:400}}>
                              {cfg.label}
                            </button>
                          );
                        })}
                      </div>
                    </div>
                    {temProb&&(
                      <input value={zd.obs||""} onChange={e=>updateZona(zona,"obs",e.target.value)}
                        placeholder="Observação..." style={{...S.inp,fontSize:12,marginTop:2}}/>
                    )}
                  </div>
                );
              })}
            </div>

            <button onClick={salvar} disabled={saving} style={{...S.btnGreen,opacity:saving?0.7:1}}>
              {saving?"⟳ Salvando...":"✓ Finalizar Teste"}
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ── LISTA / ARQUIVO
  const ultimoTeste = testes[0]||null;

  return (
    <div style={S.page}>
      {PdfSelector}
      <div style={S.wrap}>
        <div style={{position:"sticky",top:0,zIndex:10,...S.hdrBg,padding:"14px 16px"}}>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <button onClick={onBack} style={S.backBtn}>← Voltar</button>
            <div style={{flex:1}}>
              <div style={{fontSize:15,fontWeight:800,...S.txt}}>🔒 Teste Perimetral</div>
              <div style={{fontSize:11,...S.txt2}}>P505 · {testes.length} teste(s) no total</div>
            </div>
            <button onClick={onToggleTheme} style={{background:"transparent",border:`1px solid ${dark?"#1e293b":"#cbd5e1"}`,borderRadius:8,padding:"5px 10px",cursor:"pointer",fontSize:14,...S.txt2}}>{dark?"☀️":"🌙"}</button>
          </div>
        </div>

        <div style={{padding:"12px 16px",display:"flex",flexDirection:"column",gap:10}}>

          {/* Último teste */}
          {ultimoTeste&&(
            <div style={{background:dark?"#001a2e":"#e0f2fe",border:"1px solid #0ea5e933",borderRadius:10,padding:"10px 14px",cursor:"pointer"}}
              onClick={()=>{setViewTeste(ultimoTeste);setScreen("view");}}>
              <div style={{fontSize:10,color:"#0ea5e9",fontWeight:700,textTransform:"uppercase",marginBottom:4}}>📋 Último Teste</div>
              <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
                <div>
                  <div style={{fontSize:13,fontWeight:700,...S.txt}}>
                    {ultimoTeste.turno==="Diurno"?"☀️":"🌙"} {ultimoTeste.turno} · {fmtDate(ultimoTeste.data)}
                  </div>
                  <div style={{fontSize:11,...S.txt2}}>{ultimoTeste.quemFez||"—"} · {ultimoTeste.hora}</div>
                </div>
                <span style={{...S.txt2,fontSize:16}}>›</span>
              </div>
            </div>
          )}

          <button onClick={()=>{setForm(emptyTeste(undefined,pcfg));setScreen("form");}} style={S.btn}>
            + Novo Teste Perimetral
          </button>

          {/* Filtros arquivo */}
          {testes.length>0&&(
            <>
              <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                {["Todos","Diurno","Noturno"].map(f=>(
                  <button key={f} onClick={()=>setFiltroTurno(f)}
                    style={{...S.btnSm,color:filtroTurno===f?"#0ea5e9":dark?"#475569":"#94a3b8",border:`1px solid ${filtroTurno===f?"#0ea5e944":dark?"#0f172a":"#e2e8f0"}`,background:filtroTurno===f?dark?"#001a2e":"#e0f2fe":"transparent",fontSize:11}}>
                    {f==="Todos"?"Todos":f==="Diurno"?"☀️ Diurno":"🌙 Noturno"}
                  </button>
                ))}
                <div style={{flex:1}}/>
                {["7","15","30","all"].map(p=>(
                  <button key={p} onClick={()=>setFiltroPeriodo(p)}
                    style={{...S.btnSm,color:filtroPeriodo===p?"#a855f7":dark?"#475569":"#94a3b8",border:`1px solid ${filtroPeriodo===p?"#a855f744":dark?"#0f172a":"#e2e8f0"}`,background:filtroPeriodo===p?dark?"#120a2e":"#f3e8ff":"transparent",fontSize:11}}>
                    {p==="all"?"Tudo":`${p}d`}
                  </button>
                ))}
              </div>

              {/* PDF Consolidado — apenas PIN gerencial */}
              {adminAuth && (
              <div style={{display:"flex",gap:6,alignItems:"center"}}>
                <button onClick={()=>{
                  if(modoSelecao){
                    if(selecionados.length>0){
                      const periodo = `${selecionados.length} teste(s) selecionado(s)`;
                      const testsSelected = testesFiltrados.filter(t=>selecionados.includes(t.id));
                      if(testsSelected.length!==selecionados.length){
                        alert(`Atenção: ${selecionados.length} teste(s) selecionado(s), mas apenas ${testsSelected.length} foram encontrados para gerar o PDF. Cancelado por segurança — tente selecionar novamente. Se persistir, avise o suporte.`);
                        return;
                      }
                      const totRondas = testsSelected.reduce((acc,t)=>acc+((t.rondas||[]).length),0);
                      setPdfSel({modo:"consolidado",testes:testsSelected,periodo,perim:true,rondas:totRondas>0});
                    }
                    setModoSelecao(false); setSelecionados([]);
                  } else {
                    setModoSelecao(true);
                  }
                }} style={{...S.btnSm,color:"#a855f7",border:"1px solid #a855f744",fontSize:12,padding:"8px 12px",display:"flex",alignItems:"center",gap:6,flex:1,justifyContent:"center"}}>
                  {modoSelecao
                    ? selecionados.length>0
                      ? `📄 Gerar PDF (${selecionados.length} selecionado${selecionados.length!==1?"s":""})`
                      : "📄 Selecione ao menos 1"
                    : `☐ Selecionar para PDF Consolidado`}
                </button>
                {modoSelecao && (
                  <button onClick={()=>{setModoSelecao(false);setSelecionados([]);}}
                    style={{...S.btnSm,color:"#ef4444",border:"1px solid #ef444433",fontSize:11,padding:"8px 10px"}}>✕</button>
                )}
              </div>
              )}
              {modoSelecao && (
                <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                  <button onClick={()=>setSelecionados(testesFiltrados.map(t=>t.id))}
                    style={{...S.btnSm,fontSize:10,color:"#0ea5e9",border:"1px solid #0ea5e944"}}>✓ Selecionar todos</button>
                  <button onClick={()=>setSelecionados([])}
                    style={{...S.btnSm,fontSize:10,color:"#64748b",border:`1px solid ${dark?"#1e293b":"#e2e8f0"}`}}>✕ Limpar</button>
                </div>
              )}

              {/* Arquivo agrupado por data */}
              <div style={{fontSize:10,...S.txt2,fontWeight:700,textTransform:"uppercase",letterSpacing:.8}}>
                Arquivo — {testesFiltrados.length} teste(s)
              </div>

              {sortedDates.length===0&&(
                <div style={{textAlign:"center",padding:"20px 0",fontSize:12,...S.txt2}}>Nenhum teste no período</div>
              )}

              {sortedDates.map(data=>{
                const testsDodia = grouped[data];
                return (
                  <div key={data}>
                    <div style={{fontSize:11,fontWeight:700,color:"#64748b",marginBottom:5,paddingLeft:2}}>{fmtDate(data)}</div>
                    {testsDodia.map(t=>{
                      const probs = pcfg.zonas.filter(z=>(t.zonas[z]?.status||"ok")!=="ok").length;
                      return (
                        <div key={t.id} style={{...S.card,marginBottom:6,border:`2px solid ${modoSelecao&&selecionados.includes(t.id)?"#a855f7":probs>0?"#ef444433":dark?"#0f172a":"#e2e8f0"}`}}>
                          <div style={{display:"flex",alignItems:"center",gap:10}}>
                            {/* Checkbox em modo seleção */}
                            {modoSelecao && (
                              <button onClick={()=>setSelecionados(prev=>
                                prev.includes(t.id)?prev.filter(x=>x!==t.id):[...prev,t.id]
                              )} style={{width:26,height:26,borderRadius:6,border:`2px solid ${selecionados.includes(t.id)?"#a855f7":dark?"#334155":"#cbd5e1"}`,background:selecionados.includes(t.id)?"#a855f7":"transparent",display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",flexShrink:0,fontSize:14,color:"#fff"}}>
                                {selecionados.includes(t.id)?"✓":""}
                              </button>
                            )}
                            <div style={{width:36,height:36,borderRadius:9,background:t.turno==="Diurno"?dark?"#1a2e1a":"#dcfce7":dark?"#0a0a2e":"#e0e7ff",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,fontSize:18,cursor:"pointer"}}
                              onClick={()=>{if(!modoSelecao){setViewTeste(t);setScreen("view");}}}>
                              {t.turno==="Diurno"?"☀️":"🌙"}
                            </div>
                            <div style={{flex:1,cursor:"pointer"}} onClick={()=>{
                              if(modoSelecao){
                                setSelecionados(prev=>prev.includes(t.id)?prev.filter(x=>x!==t.id):[...prev,t.id]);
                              } else {
                                setViewTeste(t);setScreen("view");
                              }
                            }}>
                              <div style={{fontSize:12,fontWeight:700,...S.txt}}>{t.turno} · {t.hora}</div>
                              <div style={{fontSize:10,...S.txt2}}>{t.quemFez||"—"}</div>
                            </div>
                            {probs>0
                              ?<span style={{fontSize:10,color:"#ef4444",fontWeight:700,background:"#1a0202",padding:"2px 8px",borderRadius:5}}>{probs} prob.</span>
                              :<span style={{fontSize:10,color:"#22c55e",fontWeight:700,background:"#021a0d",padding:"2px 8px",borderRadius:5}}>✅ OK</span>
                            }
                            {!modoSelecao&&<span style={{...S.txt2,fontSize:14}}>›</span>}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                );
              })}
            </>
          )}

          {testes.length===0&&(
            <div style={{textAlign:"center",padding:"40px 0"}}>
              <div style={{fontSize:32,marginBottom:10}}>🔒</div>
              <div style={{fontSize:13,...S.txt}}>Nenhum teste registrado ainda</div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
